import unittest

from pack import badge, wrap


class PackTest(unittest.TestCase):
    def test_wrap(self):
        self.assertEqual(wrap("x"), "(x)")

    def test_badge(self):
        self.assertEqual(badge("Y"), "(y)")


if __name__ == "__main__":
    unittest.main()

